WITH parsed AS (SELECT id, effective_from, currency, tier_prices, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers WHERE YEAR(effective_from) >= 2025) SELECT id, effective_from, avg_tier_price, AVG(lowest_price) OVER (PARTITION BY currency ORDER BY entry_price, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS lowest_price_avg_6_prior, AVG(avg_tier_price) OVER (PARTITION BY currency ORDER BY entry_price, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS avg_tier_price_avg_6, NTILE(3) OVER (PARTITION BY MONTH(effective_from), currency ORDER BY entry_price, id) AS entry_price_bucket FROM parsed WHERE effective_from >= '2025-06-01'
